const STATE_KEY = 'catalogue-overrides-v2';
const LIVE_SNAPSHOT = {"version":2,"updatedAt":"2026-08-21T22:10:00+08:00","cards":{"liga-privada-no-9-coronets":{"rank":1,"stockPin":"auto","strength":8,"quality":9,"value":10,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High","Pairings: Espresso, dark chocolate, Whiskey","Occasion: Relaxed session, after a meal, outdoor smoke"],"eyebrow":"No. 1 — Best overall dark-profile fit","summaryHtml":"<strong>Earth, espresso, black pepper, dark cocoa and a trace of sweetness</strong> arrive in unusually dense smoke for the format. The draw is normally open with enough resistance to keep it controlled, while the compact roll tends to burn evenly as long as it is not chain-puffed; rushing it can make the final stretch hot. Its aroma is deep and savoury rather than perfumed, and the mouthfeel is creamy, oily and almost chewy, leaving a long cocoa, earth and pepper aftertaste. The name comes from the <a href=\"https://drewestate.com/products/liga-privada/liga-privada-no-9/\" rel=\"noopener\" target=\"_blank\">ninth and final experimental blend</a> selected by Drew Estate.","noteHtml":"Exact-line taster available: Liga Privada No. 9 Short Panatela Oscuro — A$37 single.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Connecticut Broadleaf Oscuro.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"liga-t52-coronets":{"rank":2,"stockPin":"auto","strength":9,"quality":9,"value":9,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High","Pairings: Espresso, Whiskey, Cola","Occasion: Relaxed session, after a meal, outdoor smoke"],"eyebrow":"No. 2 — Best extra-dark upgrade pick","summaryHtml":"<strong>Black pepper, charred oak, salty leather, black coffee and caramel</strong> make this sharper and more aggressive than the No. 9. Construction is generally excellent, with an easy, consistent draw and a steady burn, although the small ring gauge rewards a slower cadence and can soften or run hot if smoked hard. It produces a striking amount of aromatic smoke with a meaty, spicy room note. The mouthfeel is gritty, chewy and drier than the No. 9, followed by a lingering finish of leather, caramelised sweetness and pepper.","noteHtml":"Exact-line taster available: Liga Privada T52 Short Panatela — A$47 single.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Stalk-cut Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"undercrown-maduro-coronets":{"rank":3,"stockPin":"in","strength":8,"quality":8,"value":8,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High","Pairings: Espresso, dark chocolate, Whiskey","Occasion: Relaxed session, after a meal, outdoor smoke"],"eyebrow":"No. 3 — Best maduro Coronet alternative","summaryHtml":"<strong>Dark wood, cocoa, black pepper, earth and a faint savoury sweetness</strong> give this much of the same broad Maduro vocabulary as the Liga Coronets, with less depth and polish. The draw is usually easy and smoke production is generous; the burn is broadly dependable, though individual sticks can need a relight if the puffing rhythm is too slow or become charry if rushed. Aroma is restrained compared with the Ligas, while the mouthfeel is smooth, medium-dense and slightly dry. The finish settles into cocoa and dark wood with mild pepper and occasional late bitterness. The line began when Drew Estate’s <a href=\"https://drewestate.com/411-news/drew-estate-launches-undercrown-10-flying-pig-international-exclusive/\" rel=\"noopener\" target=\"_blank\">factory rollers created their own blend</a> after being asked to smoke fewer Liga Privadas.","noteHtml":"A$13.50 single is availabe as an exact taster at Cigarworld","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">San Andrés maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"aj-fernandez-new-world-oscuro":{"rank":4,"stockPin":"auto","strength":8,"quality":8,"value":5,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High (projected)","Pairings: Espresso, dark chocolate, rum (projected)","Occasion: Quick premium smoke, after a meal, evening smoke"],"eyebrow":"No. 4 — Strongest new dark-profile candidate","summaryHtml":"<strong>Dark tobacco, espresso, cocoa, earth and black pepper</strong> are the projected centre of this compact Nicaraguan blend. AJ Fernandez specifies a dark Nicaraguan wrapper over a Jalapa binder with Ometepe, Condega and Estelí fillers, giving it a much stronger on-paper fit for a dark, roasted profile than another smooth vintage-style Honduran. The 4″ × 36 format stays properly compact while carrying enough tobacco to avoid club-cigar thinness. It remains untasted, so the intensity, finish and pairing calls are projections rather than palate-confirmed claims.","noteHtml":"A$24.11 single is currently available at Cigarworld","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Dark Nicaraguan wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 5</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"rocky-patel-sun-grown-juniors":{"rank":6,"stockPin":"auto","strength":7,"quality":7,"value":5,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High (projected)","Pairings: Espresso, dark chocolate, cola (projected)","Occasion: Relaxed session, after a meal, outdoor smoke"],"eyebrow":"No. 6 — Scored on blend and house style","summaryHtml":"<strong>Earth, white pepper, cedar, molasses and roasted espresso</strong> give the Sun Grown Juniors the strongest direct palate fit of the new Rocky Patel tins. The 4″ × 38 handmade format carries substantially more tobacco than the Cuban clubs while remaining compact, and the five-year-old Ecuadorian Sumatra wrapper gives the blend a dry, spicy sweetness rather than a flavoured character. Rocky Patel describes the line as medium-plus and highly rated; in this catalogue its combination of intensity, proper small-cigar format and A$17-per-stick pricing earns three Golds.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Ecuadorian Sumatra wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 5</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"tabernacle-broadleaf-corona":{"rank":7,"stockPin":"auto","strength":8,"quality":9,"value":2,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High","Pairings: Espresso, dark chocolate, Whiskey","Occasion: Long evening, after a meal, premium benchmark"],"eyebrow":"No. 7 — Best premium broadleaf benchmark","summaryHtml":"<strong>Dark chocolate, espresso, walnut, charred oak, earth and black pepper</strong> arrive in dense, full-bodied smoke. The firm Broadleaf roll generally draws cleanly with moderate resistance and burns steadily, although the thick wrapper can produce a slightly wavy line and rewards patient pacing. Its aroma is powerful and savoury-sweet, carrying cocoa, cedar and roasted coffee. Mouthfeel is oily, heavy and chewy, becoming malty through the middle, while the long aftertaste holds espresso, leather, oak and pepper with a trace of dark-fruit sweetness. <a href=\"https://foundationcigarcompany.com/the-tabernacle-ct-broadleaf/\" rel=\"noopener\" target=\"_blank\">The box artwork links Haile Selassie, the Solomonic line and the biblical Tabernacle that housed the Ark of the Covenant</a>.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Connecticut Broadleaf wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-o":{"rank":8,"stockPin":"auto","strength":7,"quality":7,"value":4,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, dark chocolate, Whiskey","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"No. 8 — Best premium all-rounder","summaryHtml":"<strong>Earth, cedar, roasted coffee, pepper and dark tobacco</strong> give this cigarillo a serious, savoury profile rather than a lightweight miniature one. The machine-made construction is usually consistent, with an open draw, a straight burn and ample smoke, but the narrow format can heat quickly when overpuffed. Its aroma is woody and roasted, with less sweetness than the Serie G. The smoke feels dry-creamy and medium-weight across the palate, ending on cedar, pepper and a lightly bitter cocoa note that lasts longer than expected from a cigarillo.","noteHtml":"Taster available: Oliva Serie O Petit Corona — about A$29 single.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 5</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-v-club-20":{"rank":9,"stockPin":"auto","strength":7,"quality":7,"value":9,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Espresso, dark chocolate, cola","Occasion: Quick smoke, coffee break, outdoor smoke"],"eyebrow":"No. 9 — Full Serie V character in club format","summaryHtml":"<strong>Dark chocolate, espresso, cedar, earth and pepper</strong> compress the Serie V idea into a very narrow, fast-burning club format. CigarBox describes it as carrying the Ecuadorian Sun Grown wrapper, Nicaraguan binder and specially fermented Jalapa ligero character of the larger Serie V line. The 22 ring makes cadence important, but at A$7.57 per stick it is one of the strongest value propositions in the catalogue if you are comfortable buying twenty at once.","noteHtml":"Elite despite Bronze Size: Gold Strength + Quality + Value earns a Crown, while the A$151.45 case price keeps purchase risk red.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Ecuadorian Sun Grown Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Case of 20</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"arturo-fuente-exquisitos-maduro":{"rank":10,"stockPin":"auto","strength":7,"quality":7,"value":3,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, dark chocolate, Wafer","Occasion: Relaxed session, after a meal"],"eyebrow":"No. 10 — Best full-format maduro stretch pick","summaryHtml":"<strong>Dark chocolate, espresso, cedar, molasses and black pepper</strong> come through in dense, sweet-smelling smoke. The handmade roll usually offers a deliberate draw with modest resistance and a consistent burn, although the thin Broadleaf wrapper should be handled gently and can crack if allowed to dry. Its aroma is richer and sweeter than its medium body suggests. The mouthfeel is creamy and velvety, with enough cedar tannin to stop it becoming syrupy, and the aftertaste develops into molasses, vanilla, wood and a final dusting of white pepper.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-g":{"rank":14,"stockPin":"auto","strength":6,"quality":7,"value":5,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Wafer, rum","Occasion: Quick smoke, relaxed session, after a meal"],"eyebrow":"No. 14 — Best balanced premium bridge","summaryHtml":"<strong>Sweet cedar, toasted nuts, coffee, cocoa and Cameroon spice</strong> create a softer, more aromatic counterpart to the Serie O. The draw is usually open and productive, and the burn tends to self-correct even when slightly wavy; the ash can be loose and the last section becomes hot if puffed too frequently. Its room note is sweet, nutty and woody. The smoke begins creamy and rounded, then becomes drier and more textured through the middle, leaving a finish of roasted nuts, charred cedar, earth and a faint anise-like spice.","noteHtml":"Taster available: Oliva Serie G Petit Corona — about A$29 single.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Cameroon wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 5</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"curivari-fuerte-chicos":{"rank":15,"stockPin":"auto","strength":6,"quality":7,"value":6,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Coffee, dark chocolate, Whiskey","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"No. 15 — Solid mid-range option","summaryHtml":"<strong>Black pepper over plain tobacco</strong>, with little movement beyond that. Construction is the strong point: cleanly built, with a smooth draw that needs no correction. Smoke volume responds to draw effort rather than arriving on its own, thin on a light pull and heavy on a deep one. Cadence is unforgiving and will turn harsh if pushed. The nicotine hit is substantial and lands well ahead of what the flavour suggests. The aftertaste turns light and floral with little grip, so the strength is present only while smoking.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Nicaraguan wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"davidoff-escurio":{"rank":16,"stockPin":"auto","strength":7,"quality":6,"value":9,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Espresso, Whiskey, Cola","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"No. 16 — Best dark mini cigarillo","summaryHtml":"<strong>Espresso, dark chocolate, pepper, oak and mossy earth</strong> are compressed into a very fast, polished smoke. The fine-cut construction generally lights cleanly and burns straight, with a slightly open draw; examples kept too humid can tighten, while the tiny format can make the blend present thinner and sharper than the full-size Escurio line. The aroma is noticeably dark and spicy, though the smoke texture is lighter than in the full-size Escurio line. Mouthfeel is smooth, brisk and peppery rather than oily, with a short-to-medium aftertaste of roasted grain, chocolate and cayenne-like warmth.","noteHtml":"Taster: Davidoff Escurio Petit Robusto — A$41 single; its handmade 50-ring format will smoke cooler and richer than the minis.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Habano-style wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 20</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"davidoff-nicaragua-mini-cigarillos":{"rank":18,"stockPin":"auto","strength":5,"quality":6,"value":10,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Whiskey, Cola","Occasion: Quick smoke, outdoor smoke, travel"],"eyebrow":"No. 18 — Best everyday spicy economy","summaryHtml":"<strong>Black pepper, charred cedar, dark chocolate and cream</strong> give this miniature Davidoff more edge than its neat appearance suggests. Machine-made construction is generally precise, with a free draw and straight, rapid burn; repeated puffs can make the small-format blend feel thinner and more pepper-forward. Its aroma is clean, spicy and distinctly cedary. The mouthfeel is smooth and creamy rather than gritty, with a controlled level of smoke density, and the finish holds bittersweet cocoa, cedar and a warm pepper tingle without much lingering heaviness.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 20</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"partagas-serie-club-10":{"rank":19,"stockPin":"auto","strength":6,"quality":6,"value":9,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Coffee, Whiskey, Cola","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"No. 19 — Best strong-value Cuban club","summaryHtml":"<strong>Earth, black pepper, dark cocoa, espresso and dried-fruit sweetness</strong> deliver a concentrated, unmistakably Partagás-style hit. The short-filler construction usually gives a generous draw and steady burn, but consistency is not handmade-cigar level; a rushed stick can turn hot, sour or papery. The aroma is robust, earthy and spicy, with more presence than most Cuban clubs. Mouthfeel is lean, dry and forceful rather than creamy, and the aftertaste holds pepper, charred wood and espresso. Partagás is also tied to the unusual factory tradition of the <a href=\"https://www.famous-smoke.com/cigaradvisor/buying-guides/2018-cigar-advisor-guide-partagas-cigars\" rel=\"noopener\" target=\"_blank\">lector who read aloud to rollers</a>.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"cohiba-short-10":{"rank":20,"stockPin":"auto","strength":6,"quality":6,"value":7,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Cola, citrus, rum","Occasion: Quick smoke, travel, outdoor smoke"],"eyebrow":"No. 20 — Best substantial Cuban quick smoke","summaryHtml":"<strong>Earth, coffee, leather, cedar and black pepper</strong> give the Cohiba Short more weight than the Club it replaces. At 3¼″ × 26 it sacrifices some length but gains enough diameter to move from Size Bronze to Silver, while the current A$80 ten-pack still earns Value Gold. The format is machine-made, factory-cut and individually cellophaned, with a smooth, rounded Cuban profile and roughly fifteen-minute burn.","noteHtml":"Exact-line taster available at Cigarworld for A$11.85","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">100% Cuban tobacco.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"alonso-menendez-gold-cigarillo":{"rank":21,"stockPin":"auto","strength":4,"quality":5,"value":9,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Mild (projected)","Pairings: Coffee, citrus, cola (projected)","Occasion: Quick smoke, casual volume option"],"eyebrow":"No. 21 — Volume buy after Axe","summaryHtml":"<strong>Mild Brazilian tobacco, light wood, earth and soft natural sweetness</strong> are the profile here. Brazilian listings describe the Gold cigarillo as a mild machine-made blend using Mata Norte, Mata Fina and Virginia tobaccos under a Sumatra wrapper. Its real attraction is economic: A$199 for 50 works out to just A$3.98 each, by far more interesting as a volume purchase than as a prestige cigar. The trade-off is a 22-ring format and a very large minimum commitment.","noteHtml":"One of the catalogue's strongest volume-value plays.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Sumatra wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Box of 50</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"alonso-menendez-axe-charutos":{"rank":22,"stockPin":"auto","strength":6,"quality":6,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, dark chocolate, Whiskey","Occasion: Relaxed session, outdoor smoke"],"eyebrow":"No. 22 — Best Brazilian-value outsider","summaryHtml":"<strong>Cocoa, wood, toasted earth, coffee and mild herbs</strong> give this Brazilian charuto a rustic but approachable character. The draw is often easy or slightly open, smoke output is abundant and the burn is commonly even, though the wrapper and roll show more visual and performance variation than the polished premium entries. Its aroma is warmly toasted and woody. Mouthfeel starts creamy and medium-weight before becoming drier, and the finish leaves coffee, herbs and earth with only a light bitterness when smoked patiently.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Sumatra wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 5</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"toscanello-nero-cioccolato":{"rank":27,"stockPin":"auto","strength":6,"quality":6,"value":4,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Mocha, dark chocolate, wafer","Occasion: After a meal, cool evening, short smoke"],"eyebrow":"No. 27 — Personal dark-flavour benchmark","summaryHtml":"<strong>Fire-cured smoke, dark cocoa, roasted coffee, wood and restrained sweetness</strong> make this the catalogue’s most distinctive aromatic profile. Its rustic construction is also the least predictable: the draw can be uneven or genuinely tight, while the dry-cured body may burn quickly or wander without being ruined by lack of humidification. The aroma is powerful, combining campfire Kentucky tobacco with chocolate. Mouthfeel is dense, dry and slightly chewy, and the aftertaste is long, smoky and cocoa-led with coffee bitterness. The format descends from the <a href=\"https://www.toscanocigars.com/our-history/legend/\" rel=\"noopener\" target=\"_blank\">legendary accidental birth of the Toscano cigar</a> in nineteenth-century Tuscany.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Chocolate flavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Fire-cured Kentucky tobacco.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 5</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Dry-cured</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"cao-moontrance":{"rank":28,"stockPin":"auto","strength":3,"quality":5,"value":5,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Low","Pairings: Mocha, Wafer, Biscoff","Occasion: Quick smoke, after dinner, outdoor smoke"],"eyebrow":"No. 28 — Best in-stock vanilla option","summaryHtml":"<strong>Bourbon vanilla, caramel, peach, honey and tropical fruit</strong> sit clearly above the mild tobacco base. The machine-made roll is convenient but not perfectly consistent: some cigarillos draw and burn cleanly, while others are packed tight or struggle to maintain an even line. It is exceptionally aromatic, producing a sweet, pipe-like room note that bystanders may enjoy more than the smoker. Mouthfeel is soft, syrupy and light-bodied rather than creamy or substantial, and the aftertaste fades through vanilla and fruit with little lasting tobacco depth.","noteHtml":"Nearest taster: CAO Moontrance Tubos — about A$28 single, but currently unavailable.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Cameroon wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"don-pepin-garcia-demi-tasse":{"rank":5,"stockPin":"out","strength":8,"quality":8,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: High (projected)","Pairings: Espresso, dark chocolate, rum (projected)","Occasion: After a meal, evening smoke, premium small format"],"eyebrow":"No. 5 — Untasted; premium full-bodied Nicaraguan tin","summaryHtml":"<strong>Leather, cedar and hot pepper</strong> define the projected character of this compact Don Pepin Garcia Original. The Blue Label line is handmade from Nicaraguan tobacco under an oily Habano Rosado wrapper and is positioned as full-bodied, giving the 4.5″ × 32 Demi Tasse a strong case as a genuine premium small cigar rather than a miniaturised machine-made club. At A$18.31 per stick its theoretical value is respectable for the quality tier, but the six-count commitment is still substantial and the Australian listing is currently sold out.","noteHtml":"Restock candidate: excellent format and blend fit, but there is no reason to pay or plan around it until CigarBox actually has stock.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Habano Rosado wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 6</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"kfc-ponies":{"rank":11,"stockPin":"auto","strength":7,"quality":6,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Espresso, dark chocolate, cola","Occasion: Outdoor smoke, after a meal, fire-cured comparison"],"eyebrow":"No. 11 — Best fire-cured compact","summaryHtml":"<strong>Hickory smoke, oak, earth, char, maple and natural tobacco sweetness</strong> make the Ponies the clearest New World bridge from Toscanello Nero. Drew Estate builds the line around Kentucky fire-cured leaf and describes the profile as smoky and savoury. The 4″ × 32 handmade format is much more substantial than Nero while keeping the same fire-cured logic, so the catalogue gives it Gold Strength for intensity/profile fit even though the manufacturer calls the body medium.","noteHtml":"High palate-fit prospect, but currently out of stock at Cigarhut.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Mexican San Andrés / fire-cured blend.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"ashton-aged-maduro-esquire":{"rank":12,"stockPin":"out","strength":6,"quality":7,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Mild-Medium","Pairings: Coffee, dark chocolate, dessert","Occasion: Quick smoke, after dinner, coffee break"],"eyebrow":"No. 12 — Best premium mellow-maduro tin","summaryHtml":"<strong>Dark cocoa, coffee bean, almond, cream and a soft maple-like sweetness</strong> define the Esquire Maduro more than brute strength. Ashton positions the Esquire as a small-format expression of its premium Dominican blends, and the maduro version borrows the Broadleaf-driven flavour logic of the Aged Maduro line. The 4.25″ × 32 format is long enough to feel like a real cigar rather than a tiny club, while the handmade build and ten-count tin make it a more polished option than most small-format tins here.","noteHtml":"High-quality mellow-maduro option: Gold Quality + Gold Size give it real structural appeal, but the mild-medium body and A$147.90 ten-count buy-in stop it cracking the top tier.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Connecticut Broadleaf wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-g-maduro-special-g":{"rank":13,"stockPin":"out","strength":6,"quality":7,"value":5,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate (projected)","Pairings: Coffee, dark chocolate, rum (projected)","Occasion: Short relaxed smoke, after a meal, Maduro trial"],"eyebrow":"No. 13 — Compact Maduro trial","summaryHtml":"<strong>Spice, rich cedar, cocoa and dark tobacco sweetness</strong> are the projected appeal of the Maduro Special G. Oliva describes the Serie G Maduro as medium-bodied, pairing a Mexican wrapper with the natural richness of Nicaraguan Sun Grown filler. The squat 3.75″ × 48 shape sacrifices a little length but gives considerably more tobacco and thermal stability than the narrow cigarillos. At A$15.55 per stick it is an inexpensive way to find out whether the darker Serie G suits better than the standard Cameroon expression.","noteHtml":"CigarBox lists the pack of 10 at A$155.50 and a single at A$15.55; both are currently sold out, so the single can de-risk the pack when stock returns.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Mexican Maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"kfc-ponies-sweets":{"rank":17,"stockPin":"out","strength":5,"quality":6,"value":7,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Mild-Moderate","Pairings: Espresso, Biscoff, cola","Occasion: Outdoor smoke, dessert smoke, fire-cured comparison"],"eyebrow":"No. 17 — Best size-and-value dual Gold","summaryHtml":"<strong>Smoke, hardwood, maple sweetness, barbecue spice and a sweetened finish</strong> turn the KFC formula into a more accessible sweet-and-savoury compact. Drew Estate describes the Sweets line as mellower than the original, which holds Strength to Silver, but the 4″ × 32 handmade format and A$8.60-per-stick price create an unusual structural win: both Size and Value earn Gold.","noteHtml":"<strong>First Size + Value dual-Gold card.</strong> Under the catalogue rule it sits at the top of Cheap per stick rather than creating a fourth Noteworthy subsection.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Mexican San Andrés maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"isla-del-sol-maduro-coronets":{"rank":23,"stockPin":"out","strength":6,"quality":6,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Mocha, Wafer, Biscoff","Occasion: Dessert smoke, after a meal, outdoor smoke"],"eyebrow":"No. 23 — Best coffee-infused Maduro prospect","summaryHtml":"<strong>Mocha, cocoa, vanilla, brown sugar and roasted nuts</strong> dominate from the sweetened cap onward. The draw is generally smooth and smoke output is excellent, but construction can vary: some sticks burn evenly from end to end, while others need touch-ups or become hot and bitter in the final stretch. It is one of the most aromatic entries here, with a room note closer to coffee and dessert than raw tobacco. The mouthfeel is creamy and syrupy, and the finish moves from sweet mocha toward darker espresso and toasted nuttiness. The line grew from Drew Estate’s earlier <a href=\"https://drewestate.com/products/isla-del-sol/\" rel=\"noopener\" target=\"_blank\">coffee-cigar work with Kahlúa</a>.","noteHtml":"Nearest taster: Isla del Sol Maduro Gran Corona — about A$32 single, but currently unavailable.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"java-x-press-maduro":{"rank":24,"stockPin":"auto","strength":5,"quality":6,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Mild-Moderate","Pairings: Mocha, dark chocolate, Biscoff","Occasion: Coffee break, dessert smoke, after a meal"],"eyebrow":"No. 24 — Best mocha-infused value tin","summaryHtml":"<strong>Mocha espresso, cocoa, dark chocolate and sweet roasted coffee</strong> make the Java X-Press Maduro one of the most direct flavour matches to the catalogue’s coffee-and-cocoa axis. The 4″ × 32 handmade cigar uses a Brazilian Mata Fina wrapper over Nicaraguan tobacco and is deliberately coffee/cocoa infused. Strength stays at 5 because the profile is rich rather than forceful, while Size Gold and near-benchmark A$9.90 pricing make it a sensible substantial-format Noteworthy entry.","noteHtml":"More overtly coffee-and-cocoa driven than Isla del Sol; less tobacco-forward than Tabak Especial.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Brazilian Mata Fina wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"tabak-especial-cafecita-negra":{"rank":25,"stockPin":"auto","strength":5,"quality":6,"value":6,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Mild-Moderate","Pairings: Espresso, Biscoff, dark chocolate","Occasion: Coffee break, dessert smoke, after a meal"],"eyebrow":"No. 25 — Best dark-roast infused Coronet","summaryHtml":"<strong>Dark-roast espresso, chocolate, earth, honey and vanilla</strong> give this a more tobacco-forward coffee profile than Isla del Sol. Draw consistency is the main caveat: many burn smoothly with abundant smoke, but some arrive tight or develop wrapper and cap issues after cutting, so a shallow, clean cut and moderate humidity help. The aroma is intensely coffee-like and sweet without masking the Maduro base. Its smoke is creamy, viscous and slightly firmer on the palate than Isla del Sol, with a lingering aftertaste of cocoa, roasted coffee and sweetened lips rather than fruit.","noteHtml":"Nearest taster: Tabak Especial Colada Oscuro — A$26 single, currently in stock.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">San Andrés maduro wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"cao-bella-vanilla":{"rank":26,"stockPin":"auto","strength":3,"quality":5,"value":5,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Low","Pairings: Coffee, Wafer, Biscoff","Occasion: Dessert smoke, after dinner, outdoor smoke"],"eyebrow":"No. 26 — Best pure-vanilla CAO cigarillo","summaryHtml":"<strong>Madagascar vanilla, cream, cocoa, soft cedar and baking spice</strong> lead a simpler, more dessert-focused profile than Moontrance. The draw is usually open and easy for a machine-made cigarillo, although the narrow roll can heat and turn slightly sharp when rushed. Construction is practical rather than refined: the pre-cut head, protective tin and generally uniform roll make it convenient, but occasional waviness or a relight remains possible. It is highly aromatic, with a sweet room note of vanilla pod, toasted sugar and pastry. The smoke feels light, creamy and faintly oily across the palate, leaving vanilla wafer, mild cocoa and gentle Cameroon spice in the aftertaste rather than Moontrance’s fruitier finish.","noteHtml":"Taster available: CAO Bella Vanilla Petit Corona — A$34 single.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Cameroon wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 10</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"liga-privada-no-9-short-panatela":{"rank":1,"stockPin":"auto","strength":9,"quality":9,"value":3,"size":"gold","laurel":"none","experienceTags":["Nicotine: High","Pairings: Espresso, dark chocolate, Whiskey","Occasion: Taster smoke, after dinner, slow smoke"],"eyebrow":"T1 — Best exact No. 9 taster","summaryHtml":"<strong>Espresso, dark cocoa, earth, white pepper and caramel</strong> come through with more wrapper concentration than the coronet while retaining the No. 9’s oily sweetness. The draw should carry measured resistance and the burn is normally disciplined, though the narrow ring punishes impatient puffing and can turn the final inch hot. Its aroma is dense, roasted and savoury-sweet. Mouthfeel is creamy, oily and chewy, followed by a long finish of cocoa, coffee, earth and pepper. The line began as Drew Estate’s <a href=\"https://drewestate.com/products/liga-privada/liga-privada-no-9/\" rel=\"noopener\" target=\"_blank\">private blend project</a>, built from unusually scarce tobaccos rather than a mass-market formula.","noteHtml":"Exact taster for: Liga Privada No. 9 Coronets — Tin of 10.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Connecticut Broadleaf.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"liga-privada-t52-short-panatela":{"rank":2,"stockPin":"auto","strength":9,"quality":9,"value":2,"size":"gold","laurel":"none","experienceTags":["Nicotine: High","Pairings: Black coffee, dark chocolate, Rye Whiskey","Occasion: Taster smoke, after a meal, slow smoke"],"eyebrow":"T2 — Best exact T52 taster","summaryHtml":"<strong>Black pepper, espresso, cedar, leather and dark cocoa</strong> make this the sharper, drier Liga taster. Construction is typically firm and smoke output is huge, with a clean draw and stable burn when paced slowly; the slender ring intensifies the wrapper and can become severe if rushed. Aroma is spicy, meaty and charred rather than sweet. The mouthfeel is dense, gritty and chewy, and the aftertaste holds leather, roasted coffee, molasses and pepper for a long time.","noteHtml":"Exact taster for: Liga Privada T52 Coronets — Tin of 10.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Stalk-Cut Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Sensitive Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-o-petit-corona":{"rank":3,"stockPin":"auto","strength":8,"quality":7,"value":2,"size":"gold","laurel":"none","experienceTags":["Nicotine: Moderate-High","Pairings: Coffee, dark chocolate, Whiskey","Occasion: Taster smoke, after dinner, slow smoke"],"eyebrow":"T3 — Taster for Oliva Serie O Cigarillos","summaryHtml":"<strong>Earth, cedar, black pepper and roasted coffee</strong> make this a better read on the Serie O blend than the cigarillo tin. The handmade construction should feel firmer and more deliberate, with a steadier burn and more textured smoke, while the draw stays easy if you keep a measured pace. Aroma leans woody and savoury rather than sweet. The mouthfeel is denser than the cigarillos, and the finish lingers with toasted earth, pepper and bitter cocoa.","noteHtml":"De-risks: Oliva Serie O Cigarillos.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-v-melanio-no4":{"rank":4,"stockPin":"auto","strength":8,"quality":9,"value":2,"size":"gold","laurel":"none","experienceTags":["Nicotine: High","Pairings: Espresso, dark chocolate, rum","Occasion: Premium taster, after dinner, slow smoke"],"eyebrow":"T4 — Premium Serie V benchmark","summaryHtml":"<strong>Espresso, dark cocoa, cedar, toasted nuts and black pepper</strong> sit inside a richer, slower-burning expression of Oliva's Jalapa ligero style. Oliva describes Serie V Melanio as hand rolled with expertly fermented ligero filler, Nicaraguan binder and an Ecuadorian wrapper; the #4 keeps that blend in a compact 4.5″ × 46 format. It is expensive at A$49.90, but it gives the catalogue a genuinely premium Oliva benchmark without requiring a box purchase.","noteHtml":"Premium benchmark rather than a volume buy: three Golds earn a Crown, while Value remains Bronze.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Ecuadorian Sumatra.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"oliva-serie-g-petit-corona":{"rank":5,"stockPin":"auto","strength":6,"quality":7,"value":2,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Wafer, Biscoff","Occasion: Taster smoke, afternoon smoke, relaxed pace"],"eyebrow":"T5 — Taster for Oliva Serie G Cigarillos","summaryHtml":"<strong>Cedar, toasted nuts, gentle spice and coffee</strong> show the sweeter, rounder side of the Serie G line. Compared with the cigarillos, the handmade format should burn slower, give a cleaner draw and put more focus on aroma and texture instead of speed. The room note is nuttier and a little sweeter than the Serie O. Mouthfeel is smoother and more supple, and the aftertaste hangs on with cedar, dry cocoa and a light pepper tickle.","noteHtml":"De-risks: Oliva Serie G Cigarillos.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Cameroon.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"davidoff-escurio-petit-robusto":{"rank":6,"stockPin":"auto","strength":7,"quality":8,"value":2,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Espresso, dark chocolate, Rum","Occasion: Taster smoke, after dinner, short premium smoke"],"eyebrow":"T6 — Best Escurio flavour taster","summaryHtml":"<strong>Chilli pepper, oak, dark chocolate, liquorice and salted earth</strong> show the Escurio blend with far more depth than the mini cigarillos. The broad, short format usually gives an easy draw, even burn and cooler temperature, making construction differences between the two formats obvious. Aroma is dark, spicy and lightly sweet. Mouthfeel is creamy at first, then earthy and leathery, while the finish carries salt, roasted grain, cocoa and a mild pepper warmth without the minis’ abrupt fade.","noteHtml":"Closest flavour taster for: Davidoff Escurio Mini Cigarillos — Pack of 20. Currently unavailable.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Ecuadorian Habano.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"cohiba-short-single":{"rank":7,"stockPin":"auto","strength":6,"quality":6,"value":5,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Cola, citrus, rum","Occasion: Taster smoke, quick smoke, travel"],"eyebrow":"T7 — Taster for Cohiba Short 10","summaryHtml":"<strong>Earth, coffee, leather and pepper</strong> let you test the exact Cohiba Short format before committing to the ten-pack. Because the single is the same factory-cut 3¼″ × 26 cigar sold by Cigarworld, it is a much cleaner de-risking tool than using a different Cohiba vitola as a proxy.","noteHtml":"De-risks: Cohiba Short — Pack of 10 at Cigarhut.","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">100% Cuban tobacco.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"tabak-especial-colada-oscuro":{"rank":9,"stockPin":"auto","strength":5,"quality":6,"value":1,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Espresso, dark chocolate, Biscoff","Occasion: Taster smoke, coffee break, dessert smoke"],"eyebrow":"T9 — Taster for Tabak Especial Cafecita Negra","summaryHtml":"<strong>Espresso, dark chocolate, sweet cream and roasted coffee</strong> put the Colada squarely in the darker Tabak Especial family. The 38-ring handmade format gives you more tobacco and a longer read on the blend than the 32-ring Cafecita while keeping the commitment to one cigar. The Oscuro/Negra expression uses a dark Connecticut Broadleaf wrapper over a Sumatra binder and Nicaraguan filler, with coffee infusion layered through the profile. Expect a richer, more substantial test of whether the Cafecita Negra tin’s coffee-and-cocoa direction suits you before buying ten.","noteHtml":"De-risks: Drew Estate Tabak Especial Cafecita Negra — Tin of 10.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Connecticut Broadleaf maduro.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"cao-bella-vanilla-petit-corona":{"rank":10,"stockPin":"auto","strength":3,"quality":6,"value":1,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Low","Pairings: Coffee, Wafer, Biscoff","Occasion: Dessert smoke, vanilla test, after dinner"],"eyebrow":"T10 — Best low-commitment vanilla experiment","summaryHtml":"<strong>Madagascar vanilla, cream, toasted sugar, cocoa and gentle Cameroon spice</strong> are delivered with substantially more tobacco presence than the Bella Vanilla cigarillo. The handmade 40-ring roll should offer a freer, more even draw and a cooler burn, although the delicate wrapper and cap reward a shallow cut and a patient cadence. Its aroma is pronounced and pastry-like, carrying vanilla pod, caramel and sweet wood. Smoke texture is creamy and fuller across the tongue than the narrow cigarillo, with mild oiliness and a longer finish of vanilla wafer, cocoa and dry cedar. The single-cigar option makes this the sensible way to test CAO's vanilla profile without committing to a full tin.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">African Cameroon wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"isla-del-sol-maduro-gran-corona":{"rank":8,"stockPin":"out","strength":6,"quality":6,"value":1,"size":"gold","laurel":"auto","experienceTags":["Nicotine: Mild-Moderate","Pairings: Coffee, dark chocolate, Rum","Occasion: Taster smoke, dessert smoke, gentle pace"],"eyebrow":"T8 — Taster for Isla del Sol Maduro Coronets","summaryHtml":"<strong>Sweet coffee, cocoa, earth and brown sugar</strong> give you a fuller read on the Isla del Sol profile than the tiny coronets. The handmade build should be more even and less fussy, with a smoother draw and a slower, cooler burn. Aroma is cafe-like and friendly. The smoke feels soft, a little creamy and lightly sweet on the tongue, finishing with mocha, sugared earth and a mild Maduro bitterness that sits quietly rather than biting.","noteHtml":"De-risks: Isla del Sol Maduro Coronets, but this taster is currently unavailable.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Maduro.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Forgiving Cadence</span>","archived":false,"archivedAt":""},"cao-moontrance-tubos":{"rank":11,"stockPin":"auto","strength":4,"quality":5,"value":1,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Mild","Pairings: Coffee, white chocolate, Rum","Occasion: Taster smoke, sweet smoke, casual pace"],"eyebrow":"T11 — Taster for CAO Moontrance Cigarillos","summaryHtml":"<strong>Peach, honey, vanilla cream and floral sweetness</strong> make this the cleanest blind-buy test for Moontrance, even though it is still a sweet novelty smoke. The tube format should protect construction better than a loose cigarillo and slow the smoke down enough to separate the fruit perfume from the base tobacco. Aroma is openly sweet and perfumed. The mouthfeel is soft and slightly syrupy, and the finish leaves honeyed fruit, vanilla and a floral aftertaste that will either charm you or piss you off fast.","noteHtml":"De-risks: CAO Moontrance Cigarillos, but this taster is currently unavailable.","productionHtml":"<span class=\"artmeta-line\">Flavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Cameroon.</span>","practicalHtml":"<span class=\"artmeta-line\">Single tubo</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":false,"archivedAt":""},"partagas-serie-puritos":{"rank":17,"stockPin":"auto","strength":7,"quality":6,"value":4,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate-High","Pairings: Coffee, Whiskey, Cola","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"Archived — Best punchy Cuban step-up","summaryHtml":"<strong>Earth, cedar, pepper, toasted nuts and leather</strong> make this a blunt, savoury purito with little decorative sweetness. The draw is normally smooth but can tighten around the middle, and the machine-made burn is generally straight so long as the cigar is not puffed like a cigarette. Aroma is bold, spicy and wood-heavy. The smoke feels dry, compact and increasingly forceful across the palate, with an aftertaste of black tea, pepper and leather that becomes more assertive near the end.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 5</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T15:11:08.325Z","archivedRank":17},"romeo-y-julieta-puritos":{"rank":30,"stockPin":"auto","strength":4,"quality":5,"value":3,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Cola, citrus, Margarita","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"Archived — Best new Cuban budget match","summaryHtml":"<strong>Cedar, toast, walnut, floral sweetness and mild spice</strong> produce a fragrant, balanced Cuban profile. Direct tasting found an easy draw and a steady, cool burn even when pushed, with the flavour building noticeably toward the final third. Its aroma is one of its stronger qualities, mixing floral tobacco, toast and cedar. Mouthfeel is initially light and creamy before drying across the tongue, and the aftertaste stays clean and moderately short, leaving walnut, toast and a small pepper prickle rather than heavy earth.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T15:01:29.774Z","archivedRank":30},"montecristo-club":{"rank":22,"stockPin":"auto","strength":4,"quality":5,"value":7,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Cola, Whiskey","Occasion: Quick smoke, travel, outdoor smoke"],"eyebrow":"Archived — Best quick Montecristo value","summaryHtml":"<strong>Dry cocoa, cedar, toasted almond, earth and espresso</strong> provide a compact version of the familiar Montecristo profile. The draw is normally smooth and easy, and the burn is dependable, but this club strongly rewards light, slow puffs because overheating flattens the sweetness and exaggerates bitterness. Its aroma is sweet tobacco, wood and roasted nuts. Mouthfeel is lean but lightly creamy, and the medium-length finish holds cocoa, coffee and cedar rather than the deeper leather found in Joyitas.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T15:00:21.190Z","archivedRank":22},"romeo-y-julieta-mini-10":{"rank":21,"stockPin":"auto","strength":3,"quality":5,"value":9,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Low-Moderate","Pairings: Coffee, citrus, Cola","Occasion: Very quick smoke, travel, outdoor smoke"],"eyebrow":"Archived — Best low-cost mild Cuban mini","summaryHtml":"<strong>Mild cedar, hay, floral sweetness and light toast</strong> give this a soft, unobtrusive profile suited to a very brief smoke. The draw is usually smooth and the burn starts cleanly, although the tiny format can become hot and bitter in the second half if puffed too quickly. Aroma is pleasant and lightly floral without filling the room. Mouthfeel is airy and low-density, with almost no oiliness, and the aftertaste is short and clean when paced well; rushed examples leave a sharper papery bitterness.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Pack of 10</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T15:00:06.722Z","archivedRank":21},"punch-mini-20-tin":{"rank":19,"stockPin":"auto","strength":5,"quality":6,"value":10,"size":"bronze","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Whiskey, Cola","Occasion: Quick smoke, travel, outdoor smoke"],"eyebrow":"Archived — Best full-flavour Cuban mini","summaryHtml":"<strong>Leather, black pepper, dry earth and toasted almond</strong> create a fuller, drier profile than most cigarette-sized minis. The draw can be firm and varies across a tin, while thin wrappers are sensitive to drying and may produce an uneven or fast burn; gentle storage and slow puffs improve both. Aroma is straightforward Cuban tobacco with straw and pepper rather than perfume. Mouthfeel is lean and slightly abrasive, with little creaminess, and the aftertaste is a persistent mix of pepper and toasted nuts that can become bitter if the tiny cigar is allowed to overheat.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Machine-made</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Tin of 20</span><span class=\"artmeta-line\">Cut</span><span class=\"artmeta-line\">Protected</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T14:58:44.705Z","archivedRank":19},"montecristo-joyitas":{"rank":18,"stockPin":"auto","strength":5,"quality":7,"value":3,"size":"silver","laurel":"auto","experienceTags":["Nicotine: Moderate","Pairings: Coffee, Cola, Whiskey","Occasion: Quick smoke, after a meal, outdoor smoke"],"eyebrow":"Archived — Best handmade Cuban small format","summaryHtml":"<strong>Cedar, leather, cocoa, cream, nuts and gentle spice</strong> unfold with more nuance than the machine-made Cuban formats below it. Handmade construction usually provides a smooth draw with mild resistance and an even burn, although the slender ring gauge naturally runs faster and can need a small touch-up. The cold and burning aromas are warm, leathery and nutty. Mouthfeel is supple and medium-rich, becoming creamier through the middle, while the finish leaves leather, coffee, cocoa and a mild return of pepper. Montecristo took its name from <a href=\"https://www.habanos.com/en/the-habanos-brands-academia/montecristo-brand/\" rel=\"noopener\" target=\"_blank\">Dumas’s novel read aloud to Havana cigar rollers</a>.","noteHtml":"","productionHtml":"<span class=\"artmeta-line\">Unflavoured</span><span class=\"artmeta-line\">Handmade</span><span class=\"artmeta-line\">Undisclosed Cuban wrapper.</span>","practicalHtml":"<span class=\"artmeta-line\">Single cigar</span><span class=\"artmeta-line\">Uncut</span><span class=\"artmeta-line\">Fragile</span><span class=\"artmeta-line\">Lenient Cadence</span>","archived":true,"archivedAt":"2026-08-20T14:58:13.074Z","archivedRank":18}},"sections":{"legendHtml":"<div><b>Strength / Quality</b> Editorial 1–10. Gold ≥7, Silver 5–6, Bronze ≤4.</div><div><b>Strength anchors</b> Strength encodes intensity <i>and</i> profile fit, not raw nicotine. Reference points from direct tasting: H. Upmann Half Corona = 3 (Cuban handmade, 3.5″ × 44). Romeo y Julieta Puritos = 4 (Cuban machine-made, 3.9″ × 26). Toscanello Nero = 6 (fire-cured Italian, 3″ × 34). Rocky Patel Vintage 1990 Half Corona = 6 (Honduran handmade, Connecticut Broadleaf). Note that this and Toscanello Nero share a 6 with very different finishes: the Toscano persists for hours, the Rocky Patel fades like the Upmann. Strength captures the peak, not how long it lasts.</div><div><b>Size</b> Gold: ring ≥32 and length ≥4″. Silver: ring ≥26 or length ≥4″. Bronze: neither.</div><div><b>Value</b> value = 6 − 3.5·log₂(price ÷ benchmark), rounded to 1–10. Benchmarks: Q1 A$1.75, Q2 A$2.50, Q3 A$3.50, Q4 A$5, Q5 A$7, Q6 A$10, Q7 A$14, Q8 A$18, Q9 A$22, Q10 A$26.</div><div><b>Risk</b> Lowest cash commitment needed to test the profile. An in-stock taster can replace the pack price. Green &lt;A$50, amber A$50–100, red &gt;A$100.</div><div><b>Cadence</b> Lenient: tolerates a normal pace. Forgiving: tolerates interruption and relighting. Sensitive: punishes rushing with heat.</div><div><b>Packaging</b> Protected: tin or rigid box. Fragile: card or paper. Dry-cured: shelf-stable, no humidification required.</div><div><b>Pairing families</b> Amplify = shared compound families, so both taste more like themselves; fire-cured, maduro, broadleaf, oscuro and heavy-fermentation profiles pair with espresso, mocha, dark chocolate, Biscoff, wafer or cola. Complement = pleasant contrast without reinforcement; Cuban blends generally, Connecticut shade and Cameroon pair with cola, citrus, margarita, agave or rum.</div><div><b>Laurels</b> Three Golds = Crown. Four Golds = Gem. Crown and Gem require Strength 5 or above. Volume only pays off above the intensity floor.</div><div><b>Tiers</b> Elite: Gold on both Strength and Quality. Strong: Gold on one. Noteworthy: Gold on neither. Size and Value do not affect tier — Size is a scope filter, and Value is a buying decision rather than a judgement about the cigar. Elite additionally requires Strength 5 or above.</div><div><b>Asterisk</b> Stock unconfirmed. Excluded from automatic checks pending a call to the retailer.</div>","benchmarksHtml":"\n<p><b>Use this as a diagnostic map.</b> Flavour reactions transfer to related packs. Draw, heat, burn and mouthfeel mostly transfer when dimensions and construction are similar. One bad draw in a handmade Cuban should not condemn every Cuban pack.</p>\n<div class=\"test-impact-grid\">\n<div class=\"test-impact-item\"><b>Montecristo Joyitas</b><strong>Strong effect:</strong> Montecristo Club 10. <strong>Weak effect:</strong> Cohiba Short 10. Liking its cocoa, leather, coffee and dry Cuban character raises confidence in the Montecristo Club. Disliking its heat or narrow draw also weighs against the even thinner Club. A single construction fault should count far less.</div>\n<div class=\"test-impact-item\"><b>Romeo y Julieta Puritos</b><strong>Strong effect:</strong> Romeo y Julieta Mini 10. If the Puritos feels too mild, papery, hot or insubstantial, the Mini should drop hard because it exaggerates those traits. If you enjoy the RyJ aroma and flavour, the Mini gets a moderate boost, with the warning that it is thinner, faster and less dense.</div>\n<div class=\"test-impact-item\"><b>H. Upmann Half Corona</b><strong>Moderate effect:</strong> Cohiba Short 10. <strong>Weak effect:</strong> Montecristo Club 10. Enjoying its cream, nuts, coffee, cedar and smooth Cuban aroma helps those compact Cuban machine-made formats. Enjoying it mainly for the broad ring gauge, cool smoke and dense handmade mouthfeel does not transfer much to narrow machine-made packs.</div>\n<div class=\"test-impact-item\"><b>Rocky Patel Vintage 1990 Half Corona</b>\n<strong>Strong effect:</strong> Rocky Patel Sun Grown Juniors. Same Honduran factory, same Dominican and Nicaraguan filler, same Nicaraguan binder; the wrapper is the only variable between them. The 1990 smoked at strength 6 with excellent construction and a very smooth draw, but its mouthfeel and aftertaste matched the H. Upmann Half Corona, which is the exact reason the Upmann was not repurchased. It paired well with both citrus and coffee, which reflects a short finish clashing with little rather than genuine versatility. The 1990 carries the darkest wrapper in the Vintage line and still failed on persistence, so any Rocky Patel small format should be treated as unlikely to deliver a lasting finish until proven otherwise. <strong>Weak effect:</strong> Foundation The Tabernacle CT Broadleaf Corona. Shared broadleaf wrapper, different maker, so the read carries only lightly. <strong>Purchase note:</strong> A$95 for a pack of 5 is A$19 per stick, bronze band. Declined.</div>\n<div class=\"test-impact-item\"><b>Curivari Fuerte Chicos</b><strong>Moderate effect:</strong> Davidoff Nicaragua Mini 20 and Partagás Serie Club 10. <strong>Weak effect:</strong> Undercrown Maduro Coronets. Liking Curivari's dry earth, pepper, cocoa and intensity helps the first two. Disliking its dryness or pepper lowers them. Undercrown remains viable because it is sweeter, smoother and more Maduro-driven.</div>\n</div>\n<div class=\"test-impact-summary\"><b>Impact summary:</b> Joyitas → Montecristo Club 10; RyJ Puritos → RyJ Mini 10; H. Upmann Half Corona → Cohiba Short 10; Curivari Fuerte Chicos → Davidoff Nicaragua Mini 20 and Partagás Serie Club 10; RP Vintage 1990 Half Corona -&gt; RP Sun Grown Juniors.</div>\n"}};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}})}
function meaningful(state){if(!state||typeof state!=='object')return false;const cards=state.cards&&typeof state.cards==='object'?state.cards:{};const sections=state.sections&&typeof state.sections==='object'?state.sections:{};return Object.keys(cards).length>0||Object.keys(sections).length>0}
export default{async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/catalogue-overrides'){if(request.method==='GET'){let saved=await env.CATALOGUE_STATE.get(STATE_KEY,'json');if(!meaningful(saved)){for(const legacyKey of ['catalogue-overrides-v1','catalogue-overrides']){const legacy=await env.CATALOGUE_STATE.get(legacyKey,'json');if(meaningful(legacy)){saved={version:2,cards:legacy.cards||{},sections:legacy.sections||{},migratedAt:new Date().toISOString()};await env.CATALOGUE_STATE.put(STATE_KEY,JSON.stringify(saved));break}}}return json(meaningful(saved)?saved:LIVE_SNAPSHOT)}if(request.method==='PUT'){const origin=request.headers.get('origin');if(origin&&origin!==url.origin)return json({error:'Cross-origin writes are not allowed.'},403);const contentLength=Number(request.headers.get('content-length')||0);if(contentLength>750000)return json({error:'Catalogue override payload is too large.'},413);let payload;try{payload=await request.json()}catch(_){return json({error:'Invalid JSON.'},400)}if(!payload||typeof payload!=='object'||Array.isArray(payload))return json({error:'Invalid catalogue state.'},400);const cards=payload.cards&&typeof payload.cards==='object'&&!Array.isArray(payload.cards)?payload.cards:{};const sections=payload.sections&&typeof payload.sections==='object'&&!Array.isArray(payload.sections)?payload.sections:{};const clean={version:2,cards,sections,savedAt:new Date().toISOString()};const encoded=JSON.stringify(clean);if(encoded.length>750000)return json({error:'Catalogue override payload is too large.'},413);await env.CATALOGUE_STATE.put(STATE_KEY,encoded);return json({ok:true,savedAt:clean.savedAt})}return json({error:'Method not allowed.'},405)}return env.ASSETS.fetch(request)}};
